import{_ as o,o as r,c as n,ag as s}from"./chunks/framework.DzGOF12C.js";const _=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"philosophy/Phenomenology/04. 하이데거.md","filePath":"philosophy/Phenomenology/04. 하이데거.md"}'),l={name:"philosophy/Phenomenology/04. 하이데거.md"};function i(a,t,g,p,e,d){return r(),n("div",null,[...t[0]||(t[0]=[s('<h2 id="_1-현존재" tabindex="-1">1. 현존재 <a class="header-anchor" href="#_1-현존재" aria-label="Permalink to &quot;1. 현존재&quot;">​</a></h2><p>거기에 있음, 존재가 나타남, 존재를 이해하는 존재자.</p><ol><li>실존</li><li>존재 이해</li><li>기초 존재론의 주제</li></ol><p><strong>실존</strong>: 현존재의 존재. 오직 그때그때 어떤 세계가 나타남. 어떤 존재가 나타남이 현존재의 본질.</p><p><strong>존재 이해</strong>: 다른 존재와 달리 현존재는 자신과 세계의 존재를 이해함.</p><p><strong>기초 존재론의 주제</strong>: 현존재만이 존재에 의문을 가짐. 의문을 던지는 현존재에 대한 이해가 선행되어야 함. 존재란 현존재가 세계 속에서 이해하고 관계 맺은 총합이며, 현존재에 대한 이해가 선행되어야 함.</p><h2 id="_2-현상학-개념" tabindex="-1">2. 현상학 개념 <a class="header-anchor" href="#_2-현상학-개념" aria-label="Permalink to &quot;2. 현상학 개념&quot;">​</a></h2><p>그것 자체에서부터 보이는 대로, 그것 자체에서부터 보이도록 함 → <strong>존재론, 해석학이기도 함</strong>.</p><p><strong>후설과의 차이</strong>: 존재론과 현상학이 분명하게 구분되지 않음.</p><h2 id="_3-개요" tabindex="-1">3. 개요 <a class="header-anchor" href="#_3-개요" aria-label="Permalink to &quot;3. 개요&quot;">​</a></h2><p><strong>세계-내-존재</strong></p><ol><li>세계: 눈 앞에 있음, 손 안에 있음</li><li>안에 있는 자: 함께 있음, 세인</li><li>안에 있음: 처함, 이해, 말, 빠짐</li></ol><p><strong>눈앞에 있음은 법칙, 손안에 있음은 도구, 안에 있음은 인간을 대상</strong>으로 함.</p><p><strong>염려</strong>: 현존재의 삶 전체를 아우르는 구조를 파악하게 해주는 핵심 틀. 자신을 앞서 / 이미 세계 안에 있으면서 / 어떤 존재자 곁에 있음.</p><p><strong>본래성</strong>: 현존재가 자신을 현존재 자체로 이해함 — 불안, 죽음, 결단.</p><p><strong>시간성</strong>: 현존재의 근본적인 구조 — 장래, 기재, 현재.</p><h2 id="_4-세계-내-존재" tabindex="-1">4. 세계-내-존재 <a class="header-anchor" href="#_4-세계-내-존재" aria-label="Permalink to &quot;4. 세계-내-존재&quot;">​</a></h2><p><strong>세계</strong>: 현존재가 살고 있는 곳. 세계를 눈앞에 있는 존재자로 이해하면 안 되고, 생활세계적으로 이해해야 함.</p><p><strong>눈 앞에 있음</strong>: 현존재가 가치중립적 관찰과 추론에서 만나는 존재자의 존재방식. 실재의 존재방식.</p><p><strong>주위세계</strong>: 현존재에게 가장 가까운 세계이며, 주위세계부터 탐구가 시작되어야 함.</p><ul><li><strong>손 안에 있음</strong>: 현존재가 주위세계에서 만나는 존재자의 존재방식. 손안에 있음이 눈앞에 있음에 앞섬.</li><li><strong>고려</strong>: 손 안에 있는 것과 관계하는 방식 (막 사용하는 그런 것).</li></ul><p>눈 앞에 있는 건 주위세계가 아님. 주위세계는 이러한 의미연관의 전체 유의미성임.</p><p><strong>주위세계의 공간성</strong></p><ol><li><strong>가까움</strong>: 손안에 넣음 (내가 도구를 쓸 수 있게 함, 씀으로써 다른 도구를 쓸 수 있음)</li><li><strong>거리 없앰</strong>: 손 안에 넣을 수 있도록 함</li><li><strong>방향잡음</strong>: 어떤 것을 손 안에 넣을지 정함</li></ol><p>이러한 공간성은 연장적 공간성에 앞섬. (후설에 대한 차이: 실천적 태도가 인식적 태도에 앞섬)</p><h2 id="_5-안에-있는-자" tabindex="-1">5. 안에 있는 자 <a class="header-anchor" href="#_5-안에-있는-자" aria-label="Permalink to &quot;5. 안에 있는 자&quot;">​</a></h2><p>세계 안에 살고 있는 존재자.</p><p><strong>함께 있음</strong>: 함께 세계 안에 살고 있는 존재자의 존재방식. 손안에 있는 것을 함께 고려하는 자의 존재방식. 함께 있음이 눈앞에 있음에 앞섬.</p><p><strong>배려</strong>: 함께 있는 자에 대한 현존재의 관계방식. 현존재는 근본적으로 공동체임 (타인이 없어도 고독을 즐기는 것도 타인과의 관계에서, 타인의 부재에서 의미형성을 하는 것). 고려와 배려는 함께 이뤄짐 — 가령 문을 열 때(고려) 뒷사람을 신경 씀(배려). 사람을 사물처럼 대하면 고려의 성격이 강해짐.</p><p><strong>세인</strong>: 무차별한 방식으로 함께 있는 자, 일상적으로 이해된 공동체. 일상적으로 현존재는 자신을 세인으로 이해할 뿐이며, 처음에는 개인이라는 개념 없이 세인·공동체로 존재함.</p><h2 id="_6-안에-있음" tabindex="-1">6. 안에 있음 <a class="header-anchor" href="#_6-안에-있음" aria-label="Permalink to &quot;6. 안에 있음&quot;">​</a></h2><p>세계와 그 안에 살고 있는 존재자와의 관계.</p><p><strong>처함</strong>: 던져짐을 인식함의 구조. <strong>기분</strong>: 처함이 현존재에게 느껴지는 것. 특정한 세계를 선택하지 못하고 던져짐 — <strong>현존재의 가능성을 제약하는 조건이 개방됨</strong>.</p><p><strong>이해, 기획투사</strong>: 현존재가 여러 세계에 존재할 수 있음이 나타나는 근원적인 방식. 현존재의 가능성을 개방함. 가능성들을 그 자체로 객관적으로 보는 것이 아니라, 비이성적이고 실천적인 방식으로 봄.</p><p><strong>말</strong>: 처함과 이해가 이러저러하게 분절되는 방식. 말은 처함·이해와 실존론적으로 동근원적임.</p><p><strong>세인</strong>: 세상의 가치판단에 &#39;눈치&#39;를 보며 판단함.</p><ul><li><strong>빠짐</strong>: 일상적인 안에 있음. 세인이 세계 안에 있는 방식.</li><li><strong>애매성</strong>: 세인의 처함. 현존재가 처한 조건을 무차별하게 감지함 — 본질적인 것과 떠도는 말이 구별되지 않고 무차별하게 섞여 있어, 현존재가 진정한 결단을 내리지 못하게 만드는 안개 같은 상태.</li><li><strong>호기심</strong>: 세인의 이해. 현존재가 고유하지 않은 가능성에 관심을 가짐 — 무언가를 이해하기 위해 머무르지 못하고, 이것저것 닥치는 대로 관심을 가질 뿐 정작 중요한 자기 삶의 가능성에는 무관심한 상태.</li><li><strong>잡담</strong>: 세인의 말. 현존재를 통속적인 담론을 통해 해석함 — 사물의 본질을 알지 못한 채 세계의 가치관에 휩쓸려 생각함.</li></ul><p><strong>염려</strong>: 현존재에 대한 전체적인 규정. 자신을 앞서 / 이미 세계 안에 있으면서 / 어떤 존재자 곁에 있음.</p><ul><li><strong>이해</strong> (자신을 앞서): 이러저러하게 존재할 수 있으면서</li><li><strong>처함</strong> (이미 세계 안에 있으면서): 이러저러하게 존재할 수밖에 없는 채</li><li><strong>곁에 있음</strong> (어떤 존재자 곁에 있음): 이러저러한 존재자에 몰두함 — 내가 지금 현재 눈앞의 사물이나 일에 집중하는 시간적 상태</li></ul><h2 id="_7-본래성" tabindex="-1">7. 본래성 <a class="header-anchor" href="#_7-본래성" aria-label="Permalink to &quot;7. 본래성&quot;">​</a></h2><p>일상적으로 현존재는 자신을 세인으로 이해할 뿐, 현존재 자체로 이해하지 못함. 현존재가 어떻게 본래적으로 존재하는가? → 불안.</p><p><strong>불안</strong>: 탁월한 처함. 특정한 존재자가 아니라 세계 전체가 흔들리고 의미가 사라짐 — 세계내존재 자체가 드러남. <strong>불안의 원인은 외부에서 오는 게 아니라 세계내존재 자체임.</strong> 주위세계적인 손안의 것이 가라앉음.</p><p><strong>죽음</strong>: 현존재가 존재하지 않을 가능성. 타자와 무관(대체 불가능함), 넘어갈 수 없는 가능성이며, 고유한 자신이 드러남.</p><p><strong>결단</strong>: 탁월한 &#39;안에 있음&#39; (빠짐과 대조). 양심을 가지기 원함.</p><ul><li><strong>양심</strong>: 현존재의 내면의 목소리 (보통 세인으로 인해 듣지 못함)</li><li><strong>불안</strong>: 탁월한 처함 — 세계가 정해주는 대로 하지 않음</li><li><strong>탓</strong>: 탁월한 이해 — 현존재가 자신에게 책임을 물음</li><li><strong>과묵함</strong>: 탁월한 말 — 내면의 목소리를 들음</li></ul><p>→ 빠짐으로부터 벗어남.</p><p><strong>정리</strong></p><table tabindex="0"><thead><tr><th>안에 있음</th><th>결단</th><th>빠짐</th></tr></thead><tbody><tr><td>처함</td><td>불안</td><td>애매성</td></tr><tr><td>이해</td><td>탓</td><td>호기심</td></tr><tr><td>말</td><td>과묵함</td><td>잡담</td></tr><tr><td>곁에 있음</td><td></td><td></td></tr></tbody></table><h2 id="_8-시간성" tabindex="-1">8. 시간성 <a class="header-anchor" href="#_8-시간성" aria-label="Permalink to &quot;8. 시간성&quot;">​</a></h2><p>현존재의 시간성 (탈자태: 자신의 모습에서 벗어남) — 염려의 근본적인 구조이며, 통속적 시간성에 앞섬.</p><ul><li><strong>장래</strong>: 이해에서 나타나는 시간성 — 현존재의 가능성의 성격</li><li><strong>기재</strong>: 처함에서 나타나는 시간성 — 현존재의 가능성을 제약하는 조건의 시간성</li><li><strong>현재</strong>: 곁에 있음(어떤 존재자에게 몰두)에서 나타나는 시간성 — 현존재의 행동의 성격</li></ul><p>장래 → 기재 → 현재</p><p><strong>본래적 시간성</strong></p><ul><li>앞서달림 — 죽음으로 기획투사</li><li>회복 — 본래적 자신 회복</li><li>순간 — 고유한 의미를 가지는 존재자를 만남</li></ul><p><strong>비본래적 시간성</strong></p><ul><li>기대 — 특정한 존재자에 대한 가능성으로 기획투사</li><li>망각 — 고유한 자신을 잊음</li><li>현재화 — 그때그때 만나는 존재자를 만남</li></ul>',56)])])}const u=o(l,[["render",i]]);export{_ as __pageData,u as default};
